#!/usr/bin/env python3
"""Audit every published effect against its binary, source and browser listing."""

from __future__ import annotations

import argparse
import json
import pathlib
import re

from source_catalog import source_paths, source_text
from web_catalog import load_catalog

ROOT = pathlib.Path(__file__).resolve().parent.parent
REPORT = ROOT / "docs" / "EFFECT_SOURCE_AUDIT.md"
GENERATED_PREFIX = (
    "// Generated by tools/build_web_sources.py; do not edit.\n"
    "window.EMBEDDED_ASM="
)
PLACEHOLDER = re.compile(r"\b(?:TODO|FIXME|placeholder|stub)\b", re.IGNORECASE)
ATLAS_FLAG = re.compile(r"^%define ([A-Z]+) 1$", re.MULTILINE)


def load_web_sources() -> dict[str, str]:
    path = ROOT / "web" / "sources.js"
    text = path.read_text(encoding="utf-8")
    if not text.startswith(GENERATED_PREFIX) or not text.rstrip().endswith(";"):
        raise AssertionError("web/sources.js is not a generated source map")
    return json.loads(text[len(GENERATED_PREFIX):].rstrip()[:-1])


def published_entries(catalog: dict[str, object]) -> list[tuple[str, str, int]]:
    entries: list[tuple[str, str, int]] = []
    seen: set[str] = set()
    ordered = [*catalog["standalone"]]
    for parts in catalog["shows"].values():
        ordered.extend(parts)
    for name, image, size in ordered:
        if name not in seen:
            entries.append((name, image, size))
            seen.add(name)
    return entries


def role_for(name: str, catalog: dict[str, object], path: pathlib.Path) -> str:
    roles = []
    standalone = {entry[0] for entry in catalog["standalone"]}
    if name in standalone:
        roles.append("standalone")
    if name in {entry[0] for entry in catalog["shows"]["MEGA"]}:
        roles.append("MEGA")
    if name in {entry[0] for entry in catalog["shows"]["ATLAS"]}:
        roles.append("ATLAS")
    if "uber-micro-demos" in path.parts:
        roles.append("micro")
    if name in {"UBER70", "UBERSHOW", "UBER40K"}:
        roles.append("preserved")
    return ", ".join(roles)


def audit() -> tuple[list[dict[str, object]], dict[str, int]]:
    catalog = load_catalog(ROOT / "web" / "catalog.js")
    paths = source_paths()
    expanded = source_text()
    web_sources = load_web_sources()
    entries = published_entries(catalog)
    atlas = {entry[0] for entry in catalog["shows"]["ATLAS"]}
    atlas_flags = atlas.copy()
    failures: list[str] = []
    rows: list[dict[str, object]] = []

    expected_names = {name for name, _image, _size in entries}
    if expected_names - set(paths):
        failures.append("missing sources: " + ", ".join(sorted(expected_names - set(paths))))
    if set(web_sources) != set(paths):
        failures.append("web source map and source catalogue differ")

    for name, image, catalog_size in entries:
        path = paths.get(name)
        if path is None:
            continue
        binary = ROOT / f"{name}.COM"
        thumbnail = ROOT / "docs" / image
        raw = path.read_text(encoding="utf-8")
        listing = expanded[name]
        rel = path.relative_to(ROOT)
        item_failures = []

        if not binary.is_file():
            item_failures.append("binary missing")
        elif binary.stat().st_size != catalog_size:
            item_failures.append("catalogue size mismatch")
        if not thumbnail.is_file() or not thumbnail.stat().st_size:
            item_failures.append("thumbnail missing")
        if len(raw.strip()) < 4:
            item_failures.append("source empty")
        if PLACEHOLDER.search(raw):
            item_failures.append("placeholder marker")
        if web_sources.get(name) != listing:
            item_failures.append("browser source stale")
        if name in atlas:
            required = (
                f'%define EFFECT_ID "{name.lower()}"',
                "%define EFFECT_TITLE ",
                "%define EFFECT_SUMMARY ",
                "%define PALETTE ",
                "%define INSTRUMENT ",
                '%include "atlas_effect.inc"',
            )
            if any(token not in raw for token in required):
                item_failures.append("ATLAS metadata incomplete")
            flags = set(ATLAS_FLAG.findall(raw)) & atlas_flags
            if flags != {name}:
                item_failures.append("ATLAS kernel selection invalid")
            for include in ("atlas_effect.inc", "temporal.inc", "dos.inc", "palettes.inc"):
                if f"; ---- begin {include} ----" not in listing:
                    item_failures.append(f"expanded {include} missing")

        if item_failures:
            failures.append(f"{name}: " + ", ".join(item_failures))
        rows.append({
            "name": name,
            "role": role_for(name, catalog, rel),
            "size": catalog_size,
            "lines": len(raw.splitlines()),
            "browser_lines": len(listing.splitlines()),
            "source": rel.as_posix(),
            "status": "PASS" if not item_failures else "FAIL",
        })

    scene_counts = {}
    for name, rel, expected in (
        ("UBERSHOW", "archive/uber256-megademo/showcase.asm", 18),
        ("UBER40K", "archive/uber40k-dos-demo/showcase.asm", 20),
    ):
        text = (ROOT / rel).read_text(encoding="utf-8")
        match = re.search(r"^%define SCENE_COUNT (\d+)", text, re.MULTILINE)
        actual = int(match.group(1)) if match else -1
        scene_counts[name] = actual
        if actual != expected:
            failures.append(f"{name}: expected {expected} internal scenes, found {actual}")

    if failures:
        raise AssertionError("Effect/source audit failed:\n- " + "\n- ".join(failures))
    return rows, scene_counts


def markdown(rows: list[dict[str, object]], scene_counts: dict[str, int]) -> str:
    lines = [
        "# Effect source audit",
        "",
        "Generated by `python3 tools/audit_effect_sources.py --write` after a full build.",
        "It cross-checks every published binary with the browser catalogue, source map,",
        "thumbnail, byte count and real assembly file. ATLAS entries additionally require",
        "complete metadata, one selected kernel and the expanded shared implementation.",
        "",
        f"**Result: {len(rows)}/{len(rows)} published programs PASS.**",
        f"Preserved show engines expose {scene_counts['UBERSHOW']} and {scene_counts['UBER40K']} internal scenes.",
        "",
        "| Program | Role | COM bytes | Source lines | Browser listing lines | Assembly source | Status |",
        "|---|---|---:|---:|---:|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {row['name']} | {row['role']} | {row['size']} | {row['lines']} | {row['browser_lines']} | "
            f"[`{row['source']}`](../{row['source']}) | {row['status']} |"
        )
    lines.extend((
        "",
        "## What PASS means",
        "",
        "- The `.COM` exists and its exact byte count matches the published catalogue.",
        "- A non-empty, non-placeholder assembly source exists at the linked path.",
        "- A non-empty screenshot or thumbnail exists.",
        "- The browser source map contains the current source listing exactly.",
        "- Every ATLAS source has ID/title/summary, palette, MIDI program and exactly one kernel.",
        "- ATLAS browser listings include the real shared engine, DOS and palette sources.",
        "",
        "Behavioural correctness is checked separately by the Unicorn emulator suites and",
        "the archived show audits; NASM builds use `-Wall -Werror` and enforce every size gate.",
        "",
    ))
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--write", action="store_true", help="refresh docs/EFFECT_SOURCE_AUDIT.md")
    args = parser.parse_args()
    rows, scenes = audit()
    expected_report = markdown(rows, scenes)
    if args.write:
        REPORT.write_text(expected_report, encoding="utf-8")
        print(f"{REPORT.relative_to(ROOT)}: {len(rows)}/{len(rows)} PASS")
    else:
        if not REPORT.is_file() or REPORT.read_text(encoding="utf-8") != expected_report:
            raise AssertionError("docs/EFFECT_SOURCE_AUDIT.md is stale; run with --write")
        print(f"Effect/source audit: {len(rows)}/{len(rows)} PASS; "
              f"show scenes {scenes['UBERSHOW']} + {scenes['UBER40K']} PASS")


if __name__ == "__main__":
    main()
